34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (owner.getRegistrationDate() == null) {
108	            owner.setRegistrationDate(LocalDate.now());
109	        }
110	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
111	            return new ResponseEntity<>(HttpStatus.CONFLICT);
112	        }
113	        this.clinicService.saveOwner(owner);
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        headers.setLocation(UriComponentsBuilder.newInstance()
116	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
117	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
123	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
124	        if (currentOwner == null) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        currentOwner.setAddress(ownerFieldsDto.getAddress());
128	        currentOwner.setCity(ownerFieldsDto.getCity());
129	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
130	        currentOwner.setLastName(ownerFieldsDto.getLastName());
131	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
132	        this.clinicService.saveOwner(currentOwner);
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Transactional
138	    @Override
139	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        this.clinicService.deleteOwner(owner);
145	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Pet pet = petMapper.toPet(petFieldsDto);
157	        owner.setId(ownerId);
158	        pet.setOwner(owner);
159	        pet.getType().setName(null);
160	        this.clinicService.savePet(pet);
161	        PetDto petDto = petMapper.toPetDto(pet);
162	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
163	            .buildAndExpand(pet.getId()).toUri());
164	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner != null) {
172	            Pet currentPet = this.clinicService.findPetById(petId);
173	            if (currentPet != null) {
174	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
175	                currentPet.setName(petFieldsDto.getName());
176	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
177	                this.clinicService.savePet(currentPet);
178	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
179	            }
180	        }
181	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
187	        HttpHeaders headers = new HttpHeaders();
188	        Visit visit = visitMapper.toVisit(visitFieldsDto);
189	        Pet pet = new Pet();
190	        pet.setId(petId);
191	        visit.setPet(pet);
192	        this.clinicService.saveVisit(visit);
193	        VisitDto visitDto = visitMapper.toVisitDto(visit);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
195	            .buildAndExpand(visit.getId()).toUri());
196	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
197	    }
198	
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
203	        Owner owner = this.clinicService.findOwnerById(ownerId);
204	        if (owner != null) {
205	            Pet pet = owner.getPet(petId);
206	            if (pet != null) {
207	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    /**
214	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
215	     * owner using the same telephone number.
216	     *
217	     * @param owner the candidate owner to check
218	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
219	     */
220	    private boolean isDuplicateOwner(Owner owner) {
